    UiKey.TEXT_FOR_TASKS_AND_WORK_WITH_A_DATE_A_TEST_LINKED_TO_A_LESSON_USES_47047D89 to LocalizedText("For tasks and work with a date. A test linked to a lesson uses its start time.", "Для задач і робіт із датою. Тест із прив’язаним заняттям використовує його початок.", "Pre úlohy a povinnosti s dátumom. Test priradený k vyučovaniu používa jeho čas začiatku."),
    UiKey.TEXT_ENTER_A_POSITIVE_TIME_UP_TO_365_DAYS to LocalizedText("Enter a positive time, up to 365 days.", "Введіть додатний час, не більше 365 днів.", "Zadajte kladný čas, najviac 365 dní."),
    UiKey.TEXT_ACADEMIC_WORK_AND_TASKS to LocalizedText("Academic work and tasks", "Навчальна робота й задачі", "Študijné povinnosti a úlohy"),
